export function totalPaidCents(callback) {
  // Leave out orders whose owning user has been soft-deleted.
  query('users', (u) => u.deleted_at !== null, (err, deletedUsers) => {
    if (err) return callback(err);
    const deletedUserIds = new Set(deletedUsers.map((u) => u.id));
    query(
      'orders',
      (o) => o.status === 'paid' && o.deleted_at === null && !deletedUserIds.has(o.user_id),
      (err, rows) => {
        if (err) return callback(err);
        callback(null, rows.reduce((sum, o) => sum + o.total_cents, 0));
      },
    );
  });
}

